uence IS NOT NULL AND mp_reclaim_removed_sequence>mp_reclaim_before_cursor AND mp_reclaim_removed_sequence<=mp_reclaim_captured_ack AND mp_reclaim_removed_bytes>0 AND mp_reclaim_after_cursor=mp_reclaim_removed_sequence))))) CHECK(mp_retirement_state IS NULL OR typeof(mp_retirement_state) IN('text'));
